enum GameEventKind {
  economy,
  construction,
  diplomacy,
  recruitment,
  battle,
  intelligence,
  game,
}

/// A timestamped log entry generated by real simulation activity.
class GameEvent {
  const GameEvent({
    required this.id,
    required this.kind,
    required this.day,
    required this.titleKey,
    this.bodyKey,
    this.params = const {},
    this.countryId,
    this.amount,
    this.severity = 0,
  });

  final String id;
  final GameEventKind kind;
  final int day;

  /// Localization key for the headline.
  final String titleKey;

  /// Optional localization key for the body text.
  final String? bodyKey;

  /// Interpolation values for the localized strings.
  final Map<String, String> params;

  final String? countryId;
  final double? amount;

  /// -1 negative, 0 neutral, 1 positive. Drives colour coding.
  final int severity;

  Map<String, dynamic> toJson() => {
    'id': id,
    'kind': kind.name,
    'day': day,
    'titleKey': titleKey,
    'bodyKey': bodyKey,
    'params': params,
    'countryId': countryId,
    'amount': amount,
    'severity': severity,
  };

  static GameEvent fromJson(Map<String, dynamic> json) => GameEvent(
    id: json['id'] as String,
    kind: GameEventKind.values.firstWhere(
      (k) => k.name == json['kind'],
      orElse: () => GameEventKind.game,
    ),
    day: (json['day'] as num).toInt(),
    titleKey: json['titleKey'] as String,
    bodyKey: json['bodyKey'] as String?,
    params: json['params'] == null
        ? const {}
        : Map<String, String>.from(
            (json['params'] as Map).map(
              (k, v) => MapEntry(k as String, v.toString()),
            ),
          ),
    countryId: json['countryId'] as String?,
    amount: (json['amount'] as num?)?.toDouble(),
    severity: (json['severity'] as num?)?.toInt() ?? 0,
  );
}
